/* public/app/core/swipe.js — Ф3.17: свайп как на iOS для панели профиля.
Было fix-views.js: v68 (свайп) + v68 (touch-action). */
(function(){
'use strict';
var css=document.createElement('style');
css.textContent=
'@media(max-width:820px){'+
'#panel.open.swipe-hint{animation:panelNudge 1.1s cubic-bezier(.3,1.4,.4,1) 1}'+
'@keyframes panelNudge{0%{transform:none}30%{transform:translateX(-18px)}60%{transform:translateX(6px)}100%{transform:none}}'+
'.swipeHintChip{position:relative;display:table;width:fit-content;max-width:calc(100% - 8px);margin:0 auto 10px;z-index:1;background:rgba(16,20,24,.78);color:#fff;border-radius:999px;padding:8px 12px;font-size:12px;font-weight:700;line-height:1.3;text-align:center;box-sizing:border-box;pointer-events:none;animation:hintFade 1.6s forwards}'+
'@keyframes hintFade{0%{opacity:0;transform:translateX(-8px)}20%{opacity:1;transform:none}80%{opacity:1;transform:none}100%{opacity:0;transform:translateX(-8px)}}'+
'}';
document.head.appendChild(css);
var p=document.getElementById('panel');if(!p)return;
var ov=document.getElementById('overlay');
var sx=0,sy=0,dx=0,dy=0,axis=null,tracking=false,active=false,lastX=0,lastT=0,vel=0;
var cachedWidth = 0;

function setT(x){p.style.setProperty('transform','translateX('+x+'px)','important');}
function setOv(op){if(ov){ov.style.transition='none';ov.style.opacity=String(op);}}
function cleanup(){p.style.removeProperty('transform');p.style.transition='';if(ov){ov.style.transition='';ov.style.opacity='';}}

p.addEventListener('touchstart', function(e) {
  if (window.innerWidth > 820 || !p.classList.contains('open')) return;
  if (e.touches.length !== 1) return;
  cachedWidth = p.offsetWidth || innerWidth; // Замер 1 раз при старте жеста
  var t = e.touches[0]; sx = t.clientX; sy = t.clientY; lastX = sx; lastT = Date.now();
  dx = 0; dy = 0; axis = null; active = false; tracking = true; vel = 0;
}, { passive: true });

p.addEventListener('touchmove', function(e) {
  if (!tracking) return;
  var t = e.touches[0]; dx = t.clientX - sx; dy = t.clientY - sy;
  if (!axis) {
    if (Math.abs(dx) < 7 && Math.abs(dy) < 7) return;
    axis = Math.abs(dx) > Math.abs(dy) ? 'x' : 'y';
    if (axis === 'y') { tracking = false; return; }
    active = true; p.style.transition = 'none';
  }
  if (!active) return;
  if (dx < 0) dx = 0;
  var w = cachedWidth || innerWidth;
  if (dx > w) dx = w;
  setT(dx);
  setOv(1 - dx / w);
  var now = Date.now(), dt = now - lastT;
  if (dt > 0) vel = 0.8 * vel + 0.2 * ((t.clientX - lastX) / dt);
  lastX = t.clientX; lastT = now;
  if (e.cancelable) e.preventDefault();
}, { passive: false });

p.addEventListener('touchend', function() {
  if (!tracking) return;
  tracking = false;
  if (!active) return;
  active = false;
  var w = cachedWidth || innerWidth;
  var shouldClose = dx > Math.min(120, w * 0.35) || vel > 0.5;
  p.style.transition = 'transform .32s cubic-bezier(.2,1,.3,1)';
  if (ov) ov.style.transition = 'opacity .32s';
  if (shouldClose) {
    setT(w + 24); setOv(0);
    setTimeout(function() {
      if (typeof window.closePanel === 'function') {
        window.closePanel();
      } else {
        p.classList.remove('open');
        if (typeof syncOverlay === 'function') syncOverlay();
      }
      cleanup();
    }, 330);
  } else {
    setT(0); setOv(1);
    setTimeout(cleanup, 330);
  }
}, { passive: true });

// Жест остаётся доступен; визуальная подсказка по запросу удалена из профиля.
})();

(function() {
  var s = document.createElement('style');
  s.textContent = '@media(max-width:820px){#panel{touch-action:pan-y}}';
  document.head.appendChild(s);
})();
