function getTopIngredients(items) {
  var matched = [];
  INGREDIENT_GROUPS.forEach(function (grp) {
    var count = items.filter(function (p) {
      var str = ((p.name || '') + ' ' + (p.desc || '') + ' ' + (p.comp || []).join(' '));
      return grp.re.test(str);
    }).length;

    if (count >= 1) {
      matched.push({
        id: grp.id,
        label: grp.label,
        totalScore: grp.score + count * 15
      });
    }
  });

  matched.sort(function (a, b) { return b.totalScore - a.totalScore; });
  return matched.slice(0, 8);
}

function matchesIngredient(p, ingId) {
  if (!ingId || ingId === 'all') return true;
  var grp = INGREDIENT_GROUPS.find(function (g) { return g.id === ingId; });
  if (!grp) return true;
  var str = ((p.name || '') + ' ' + (p.desc || '') + ' ' + (p.comp || []).join(' '));
  return grp.re.test(str);
}

var deliverySubFilterCueResizeObserver = null;

function syncDeliverySubFilterCue(bar) {
  if (!bar) return;

  var viewport = bar.parentElement &&
    bar.parentElement.classList.contains('subfilter-viewport')
    ? bar.parentElement
    : null;

  // Until the first menu render, keep the reserved HTML slot in place.
  // After renderSubFilter decides visibility, the bar's explicit hidden state owns the slot.
  if (viewport && bar.dataset.rendered === '1') {
    viewport.hidden = bar.hidden;
  }

  var hasOverflow = !bar.hidden && bar.scrollWidth > bar.clientWidth + 1;
  var maxScroll = Math.max(0, bar.scrollWidth - bar.clientWidth);
  var atEnd = hasOverflow && bar.scrollLeft >= maxScroll - 2;

  bar.classList.toggle('has-overflow', hasOverflow);
  bar.classList.toggle('at-end', atEnd);

  if (viewport) {
    viewport.classList.toggle('has-overflow', hasOverflow);
    viewport.classList.toggle('at-end', atEnd);
  }
}

function ensureSubFilterBar() {
  var bar = document.getElementById('deliverySubFilter');
  if (!bar) {
    var grid = document.getElementById('deliveryGrid');
    if (!grid || !grid.parentNode) return null;

    // Keep the statically reserved slot so hydration does not move the product grid.
    var viewport = document.getElementById('deliverySubFilterViewport');
    if (!viewport) {
      viewport = document.createElement('div');
      viewport.id = 'deliverySubFilterViewport';
      viewport.className = 'subfilter-viewport';
      grid.parentNode.insertBefore(viewport, grid);
    }
    bar = document.createElement('div');
    bar.id = 'deliverySubFilter';
    bar.className = 'subfilter-bar';
    bar.hidden = true;
    viewport.appendChild(bar);
  }

  if (bar && !(bar.parentElement &&
      bar.parentElement.classList.contains('subfilter-viewport'))) {
    var viewport = document.createElement('div');
    viewport.className = 'subfilter-viewport';
    viewport.hidden = !!bar.hidden;
    bar.parentNode.insertBefore(viewport, bar);
    viewport.appendChild(bar);
  }

  if (bar && bar.dataset.scrollCueBound !== '1') {
    bar.dataset.scrollCueBound = '1';
    bar.addEventListener('scroll', function () {
      syncDeliverySubFilterCue(bar);
    }, { passive: true });
    window.addEventListener('resize', function () {
      syncDeliverySubFilterCue(bar);
    }, { passive: true });

    if (typeof ResizeObserver !== 'undefined' && !deliverySubFilterCueResizeObserver) {
      deliverySubFilterCueResizeObserver = new ResizeObserver(function () {
        syncDeliverySubFilterCue(bar);
      });
      deliverySubFilterCueResizeObserver.observe(bar);
    }
  }

  syncDeliverySubFilterCue(bar);
  return bar;
}

function renderSubFilter(categoryItems) {
  var bar = ensureSubFilterBar();
  if (!bar) return;
  bar.dataset.rendered = '1';

  var isAddons = (dcat === 'sauces');

  if (isAddons) {
    bar.hidden = false;
    bar.innerHTML = ADDON_TABS.map(function (tab) {
      var on = (activeAddonTab === tab.id) ? ' on' : '';
      return '<button type="button" class="subchip' + on + '" data-addon-tab="' + tab.id + '">' + tab.label + '</button>';
    }).join('');
    syncDeliverySubFilterCue(bar);
    return;
  }

  if (categoryItems.length > 5) {
    var chips = getTopIngredients(categoryItems);
    if (!chips.length) {
      bar.hidden = true;
      bar.innerHTML = '';
      syncDeliverySubFilterCue(bar);
      return;
    }
    bar.hidden = false;
    var allOn = (activeIngredient === 'all') ? ' on' : '';
    var html = '<button type="button" class="subchip' + allOn + '" data-ing="all">Все</button>';
    html += chips.map(function (c) {
      var on = (activeIngredient === c.id) ? ' on' : '';
      return '<button type="button" class="subchip' + on + '" data-ing="' + c.id + '">' + c.label + '</button>';
    }).join('');
    bar.innerHTML = html;
    syncDeliverySubFilterCue(bar);
  } else {
    bar.hidden = true;
    bar.innerHTML = '';
    syncDeliverySubFilterCue(bar);
  }
}

function renderDeliveryRail() {
  var rail = $('#deliveryRail');
  var current = new Map(
    Array.from(rail.querySelectorAll('button[data-dcat]')).map(button => [button.dataset.dcat, button])
  );
  DCATS.forEach(function (c) {
    var button = current.get(c.id);
    if (!button) {
      button = document.createElement('button');
      button.type = 'button';
      button.dataset.dcat = c.id;
      button.setAttribute('aria-label', c.l);
      button.title = c.l;
      button.innerHTML = '<span class="re">' + c.e + '</span><span class="category-label">' + esc(c.shortLabel || c.l) + '</span>';
      rail.appendChild(button);
    }
    var selected = c.id === dcat;
    button.classList.toggle('on', selected);
    button.setAttribute('aria-pressed', selected ? 'true' : 'false');
    if (selected) button.setAttribute('aria-current', 'location');
    else button.removeAttribute('aria-current');
  });
  rail.querySelectorAll('button[data-dcat]').forEach(function (button) {
    if (!DCATS.some(function (c) { return c.id === button.dataset.dcat; })) button.remove();
  });
}
